  const a=this.slots[id],s=this.states[id],previous=[s.x,s.y],elapsed=time-this.at-(a.entryDelayMs||0),path=a.entry==='path'&&a.entryPath?.length?[...a.entryPath,[a.x,a.y]]:null;
